import sys
from collections import defaultdict

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        K = int(next(iterator))
    except StopIteration:
        return

    P = []
    for _ in range(K):
        P.append(int(next(iterator)))

    adj = defaultdict(list)
    for i in range(K):
        row = next(iterator)
        for j, char in enumerate(row):
            if char == 'Y':
                adj[i].append(j)

    visited = [False] * K
    components = []

    for i in range(K):
        if not visited[i]:
            stack = [i]
            comp_indices = []
            while stack:
                u = stack.pop()
                if not visited[u]:
                    visited[u] = True
                    comp_indices.append(u)
                    for v in adj[u]:
                        if not visited[v]:
                            stack.append(v)
            components.append(comp_indices)

    result = [0] * K
    for indices in components:
        values = [P[i] for i in indices]
        values.sort()
        indices_sorted = sorted(indices)
        for idx, val_idx in enumerate(indices_sorted):
            result[val_idx] = values[idx]

    print(" ".join(map(str, result)))

if __name__ == "__main__":
    solve()
